package io.github.mucker.core.models

import org.json.JSONObject
import java.util.UUID

/**
 * Represents a rule used to intercept and mock OkHttp network requests.
 */
data class MockRule(
    val id: String = UUID.randomUUID().toString().take(8),
    val urlPattern: String,
    val method: String = "ALL", // ALL, GET, POST, PUT, DELETE, PATCH
    val statusCode: Int = 200,
    val delayMs: Long = 0,
    val responseHeaders: Map<String, String> = mapOf("Content-Type" to "application/json", "X-Mocked-By" to "Mucker"),
    val responseBody: String = "{\"status\":\"mocked\"}",
    var isEnabled: Boolean = true
) {
    /**
     * Checks if this rule matches the given HTTP method and URL.
     */
    fun matches(requestMethod: String, url: String): Boolean {
        if (!isEnabled) return false

        // Method matching
        if (method != "ALL" && !method.equals(requestMethod, ignoreCase = true)) {
            return false
        }

        // Pattern matching: check exact, glob or regex
        return try {
            if (urlPattern.contains("*") && !urlPattern.startsWith("^") && !urlPattern.startsWith(".*")) {
                // Convert simple glob pattern to regex: e.g. /api/* -> .*/api/.*
                val regexPattern = urlPattern
                    .replace(".", "\\.")
                    .replace("*", ".*")
                url.matches(Regex(regexPattern))
            } else {
                url.matches(Regex(urlPattern)) || url.contains(urlPattern)
            }
        } catch (_: Exception) {
            url.contains(urlPattern)
        }
    }

    fun toJson(): JSONObject {
        val json = JSONObject()
        json.put("id", id)
        json.put("urlPattern", urlPattern)
        json.put("method", method)
        json.put("statusCode", statusCode)
        json.put("delayMs", delayMs)
        json.put("responseBody", responseBody)
        json.put("isEnabled", isEnabled)

        val headersObj = JSONObject()
        responseHeaders.forEach { (k, v) -> headersObj.put(k, v) }
        json.put("responseHeaders", headersObj)
        return json
    }

    companion object {
        fun fromJson(json: JSONObject): MockRule {
            val headersMap = mutableMapOf<String, String>()
            if (json.has("responseHeaders")) {
                val h = json.getJSONObject("responseHeaders")
                val keys = h.keys()
                while (keys.hasNext()) {
                    val k = keys.next()
                    headersMap[k] = h.getString(k)
                }
            } else {
                headersMap["Content-Type"] = "application/json"
                headersMap["X-Mocked-By"] = "Mucker"
            }

            return MockRule(
                id = json.optString("id", UUID.randomUUID().toString().take(8)),
                urlPattern = json.getString("urlPattern"),
                method = json.optString("method", "ALL"),
                statusCode = json.optInt("statusCode", 200),
                delayMs = json.optLong("delayMs", 0),
                responseHeaders = headersMap,
                responseBody = json.optString("responseBody", ""),
                isEnabled = json.optBoolean("isEnabled", true)
            )
        }
    }
}

package io.github.mucker.core.models

/**
 * Result of a decision made for a paused request (either via CDP Fetch.fulfillRequest/continueRequest or Dashboard UI).
 */
sealed interface MockDecision {
    data class Fulfill(
        val statusCode: Int = 200,
        val headers: Map<String, String> = mapOf("Content-Type" to "application/json", "X-Mocked-By" to "Mucker-Breakpoint"),
        val body: String = ""
    ) : MockDecision

    data object Continue : MockDecision

    data class Fail(
        val errorReason: String = "Failed by client"
    ) : MockDecision
}

package io.github.mucker.core.models

import org.json.JSONObject

/**
 * Represents an inspected network request and response entry.
 */
data class NetworkRecord(
    val id: String,
    val url: String,
    val method: String,
    val headers: Map<String, String> = emptyMap(),
    val postData: String? = null,
    val timestamp: Long = System.currentTimeMillis(),
    var statusCode: Int? = null,
    var responseHeaders: Map<String, String> = emptyMap(),
    var responseBody: String? = null,
    var responseTime: Long? = null,
    var isPaused: Boolean = false,
    var isMocked: Boolean = false,
    var error: String? = null
) {
    fun toJson(): JSONObject {
        val json = JSONObject()
        json.put("id", id)
        json.put("url", url)
        json.put("method", method)
        json.put("timestamp", timestamp)
        json.put("isPaused", isPaused)
        json.put("isMocked", isMocked)
        if (statusCode != null) json.put("statusCode", statusCode)
        if (responseTime != null) json.put("responseTime", responseTime)
        if (postData != null) json.put("postData", postData)
        if (responseBody != null) json.put("responseBody", responseBody)
        if (error != null) json.put("error", error)

        val reqH = JSONObject()
        headers.forEach { (k, v) -> reqH.put(k, v) }
        json.put("headers", reqH)

        val resH = JSONObject()
        responseHeaders.forEach { (k, v) -> resH.put(k, v) }
        json.put("responseHeaders", resH)

        return json
    }
}

package io.github.mucker.server

import android.content.Context
import io.github.mucker.core.MockEngine
import io.github.mucker.core.models.MockDecision
import io.github.mucker.core.models.MockRule
import io.github.mucker.util.NetworkUtils
import org.json.JSONArray
import org.json.JSONObject

/**
 * Handles HTTP REST endpoints for Mucker Dashboard, CLI, and CDP Discovery.
 */
class RestHandler(
    private val engine: MockEngine,
    private val port: Int,
    private val context: Context?
) {
    data class HttpResponse(
        val statusCode: Int = 200,
        val contentType: String = "application/json; charset=utf-8",
        val body: String = ""
    )

    fun handle(method: String, path: String, body: String): HttpResponse {
        val cleanPath = path.split("?")[0].trimEnd('/')

        return when {
            // CDP Discovery Endpoints
            method == "GET" && cleanPath == "/json/version" -> {
                val json = JSONObject()
                json.put("Browser", "Mucker/1.0.0")
                json.put("Protocol-Version", "1.3")
                json.put("User-Agent", "Mucker In-App DevTools")
                json.put("V8-Version", "1.0.0")
                json.put("webSocketDebuggerUrl", "ws://${getWsHost()}/devtools/page")
                HttpResponse(200, "application/json", json.toString())
            }

            method == "GET" && (cleanPath == "/json/list" || cleanPath == "/json") -> {
                val array = JSONArray()
                val target = JSONObject()
                target.put("id", "mucker-inapp-target")
                target.put("type", "page")
                target.put("title", "Mucker DevTools (${context?.packageName ?: "Android App"})")
                target.put("description", "Mucker In-App OkHttp Mock Engine")
                target.put("devtoolsFrontendUrl", "devtools/inspector.html?ws=${getWsHost()}/devtools/page")
                target.put("webSocketDebuggerUrl", "ws://${getWsHost()}/devtools/page")
                target.put("url", "http://${getWsHost()}/")
                array.put(target)
                HttpResponse(200, "application/json", array.toString())
            }

            // Status Endpoints
            method == "GET" && cleanPath == "/api/status" -> {
                val json = JSONObject()
                json.put("status", "running")
                json.put("version", "1.0.0")
                json.put("port", port)
                json.put("app", context?.packageName ?: "Android App")
                json.put("breakpointMode", engine.breakpointMode)
                json.put("activeRulesCount", engine.rules.getAllRules().size)
                json.put("pausedRequestsCount", engine.getPendingPausedCount())
                val mcp = JSONObject()
                mcp.put("http", "/mcp")
                mcp.put("sse", "/sse")
                json.put("mcp", mcp)
                HttpResponse(200, "application/json", json.toString())
            }

            method == "POST" && cleanPath == "/api/status" -> {
                try {
                    val req = JSONObject(body)
                    if (req.has("breakpointMode")) {
                        engine.breakpointMode = req.getBoolean("breakpointMode")
                    }
                    HttpResponse(200, "application/json", JSONObject().put("success", true).toString())
                } catch (e: Exception) {
                    HttpResponse(400, "application/json", JSONObject().put("error", e.message).toString())
                }
            }

            // Rules Endpoints
            method == "GET" && cleanPath == "/api/rules" -> {
                HttpResponse(200, "application/json", engine.rules.toJson().toString())
            }

            method == "POST" && cleanPath == "/api/rules" -> {
                try {
                    val reqJson = JSONObject(body)
                    val rule = MockRule.fromJson(reqJson)
                    engine.rules.addRule(rule)
                    HttpResponse(200, "application/json", rule.toJson().toString())
                } catch (e: Exception) {
                    HttpResponse(400, "application/json", JSONObject().put("error", e.message).toString())
                }
            }

            method == "DELETE" && cleanPath == "/api/rules" -> {
                engine.rules.clearRules()
                HttpResponse(200, "application/json", JSONObject().put("success", true).toString())
            }

            method == "DELETE" && cleanPath.startsWith("/api/rules/") -> {
                val id = cleanPath.removePrefix("/api/rules/")
                val removed = engine.rules.removeRule(id)
                HttpResponse(200, "application/json", JSONObject().put("success", removed).toString())
            }

            method == "POST" && cleanPath == "/api/rules/toggle" -> {
                try {
                    val req = JSONObject(body)
                    val id = req.getString("id")
                    val isEnabled = req.getBoolean("isEnabled")
                    val ok = engine.rules.toggleRule(id, isEnabled)
                    HttpResponse(200, "application/json", JSONObject().put("success", ok).toString())
                } catch (e: Exception) {
                    HttpResponse(400, "application/json", JSONObject().put("error", e.message).toString())
                }
            }

            // History Endpoints
            method == "GET" && cleanPath == "/api/history" -> {
                HttpResponse(200, "application/json", engine.history.toJson().toString())
            }

            method == "DELETE" && cleanPath == "/api/history" -> {
                engine.history.clear()
                HttpResponse(200, "application/json", JSONObject().put("success", true).toString())
            }

            // Paused Request Endpoints
            method == "POST" && cleanPath.startsWith("/api/paused/") && cleanPath.endsWith("/fulfill") -> {
                val reqId = cleanPath.removePrefix("/api/paused/").removeSuffix("/fulfill")
                try {
                    val req = JSONObject(body)
                    val statusCode = req.optInt("statusCode", 200)
                    val resBody = req.optString("responseBody", "")
                    val headersMap = mutableMapOf<String, String>()
                    if (req.has("responseHeaders")) {
                        val h = req.getJSONObject("responseHeaders")
                        val keys = h.keys()
                        while (keys.hasNext()) {
                            val k = keys.next()
                            headersMap[k] = h.getString(k)
                        }
                    } else {
                        headersMap["Content-Type"] = "application/json"
                    }
                    headersMap["X-Mocked-By"] = "Dashboard"

                    val ok = engine.fulfill(reqId, MockDecision.Fulfill(statusCode, headersMap, resBody))
                    HttpResponse(200, "application/json", JSONObject().put("success", ok).toString())
                } catch (e: Exception) {
                    HttpResponse(400, "application/json", JSONObject().put("error", e.message).toString())
                }
            }

            method == "POST" && cleanPath.startsWith("/api/paused/") && cleanPath.endsWith("/continue") -> {
                val reqId = cleanPath.removePrefix("/api/paused/").removeSuffix("/continue")
                val ok = engine.continueRequest(reqId)
                HttpResponse(200, "application/json", JSONObject().put("success", ok).toString())
            }

            else -> HttpResponse(404, "application/json", JSONObject().put("error", "Not Found").toString())
        }
    }

    private fun getWsHost(): String {
        val ip = NetworkUtils.getLocalIpAddress(context)
        return "$ip:$port"
    }
}

package io.github.mucker.server

import java.io.InputStream
import java.io.OutputStream
import java.net.Socket
import java.nio.charset.StandardCharsets

/**
 * Lightweight, robust RFC 6455 WebSocket connection handler.
 */
class WebSocketConnection(
    private val socket: Socket,
    private val onMessage: (String, WebSocketConnection) -> Unit,
    private val onClose: (WebSocketConnection) -> Unit
) {
    private val inStream: InputStream = socket.getInputStream()
    private val outStream: OutputStream = socket.getOutputStream()
    @Volatile var isClosed: Boolean = false
        private set

    fun startListening() {
        Thread({
            try {
                while (!isClosed && !socket.isClosed) {
                    val message = readFrame() ?: break
                    onMessage(message, this)
                }
            } catch (_: Exception) {
            } finally {
                close()
            }
        }, "mucker-ws-${socket.port}").start()
    }

    @Synchronized
    fun sendText(text: String) {
        if (isClosed || socket.isClosed) return
        try {
            val payload = text.toByteArray(StandardCharsets.UTF_8)
            val len = payload.size

            outStream.write(0x81) // FIN + text opcode

            if (len < 126) {
                outStream.write(len)
            } else if (len <= 65535) {
                outStream.write(126)
                outStream.write((len shr 8) and 0xFF)
                outStream.write(len and 0xFF)
            } else {
                outStream.write(127)
                for (i in 7 downTo 0) {
                    outStream.write(((len.toLong() shr (8 * i)) and 0xFF).toInt())
                }
            }

            outStream.write(payload)
            outStream.flush()
        } catch (_: Exception) {
            close()
        }
    }

    private fun readFrame(): String? {
        val b0 = inStream.read()
        if (b0 == -1) return null

        val opcode = b0 and 0x0F
        if (opcode == 0x08) { // Close frame
            return null
        }

        val b1 = inStream.read()
        if (b1 == -1) return null

        val isMasked = (b1 and 0x80) != 0
        var payloadLen = (b1 and 0x7F).toLong()

        if (payloadLen == 126L) {
            val byte1 = inStream.read()
            val byte2 = inStream.read()
            if (byte1 == -1 || byte2 == -1) return null
            payloadLen = ((byte1 shl 8) or byte2).toLong()
        } else if (payloadLen == 127L) {
            payloadLen = 0
            for (i in 0 until 8) {
                val b = inStream.read()
                if (b == -1) return null
                payloadLen = (payloadLen shl 8) or b.toLong()
            }
        }

        val maskingKey = ByteArray(4)
        if (isMasked) {
            var read = 0
            while (read < 4) {
                val r = inStream.read(maskingKey, read, 4 - read)
                if (r == -1) return null
                read += r
            }
        }

        val payload = ByteArray(payloadLen.toInt())
        var totalRead = 0
        while (totalRead < payload.size) {
            val r = inStream.read(payload, totalRead, payload.size - totalRead)
            if (r == -1) return null
            totalRead += r
        }

        if (isMasked) {
            for (i in payload.indices) {
                payload[i] = (payload[i].toInt() xor maskingKey[i % 4].toInt()).toByte()
            }
        }

        return String(payload, StandardCharsets.UTF_8)
    }

    fun close() {
        if (isClosed) return
        isClosed = true
        try {
            socket.close()
        } catch (_: Exception) {}
        onClose(this)
    }
}

package io.github.mucker.server

import io.github.mucker.core.MockEngine
import io.github.mucker.core.models.CdpMessages
import io.github.mucker.core.models.MockDecision
import io.github.mucker.util.NetworkUtils
import org.json.JSONObject

/**
 * Handles incoming JSON-RPC 2.0 messages according to the Chrome DevTools Protocol Fetch & Network domains.
 */
class CdpHandler(private val engine: MockEngine) {

    fun handleMessage(rawMessage: String, connection: WebSocketConnection) {
        try {
            val json = JSONObject(rawMessage)
            val id = json.optLong("id", -1L)
            val method = json.optString("method", "")
            val params = json.optJSONObject("params") ?: JSONObject()

            when (method) {
                "Fetch.enable" -> {
                    val patternsList = mutableListOf<String>()
                    if (params.has("patterns")) {
                        val patternsArray = params.getJSONArray("patterns")
                        for (i in 0 until patternsArray.length()) {
                            val p = patternsArray.getJSONObject(i)
                            patternsList.add(p.optString("urlPattern", "*"))
                        }
                    }
                    if (patternsList.isEmpty()) {
                        patternsList.add("*")
                    }
                    engine.enableInterception(patternsList)
                    if (id != -1L) connection.sendText(CdpMessages.createRpcSuccess(id))
                }

                "Fetch.disable" -> {
                    engine.disableInterception()
                    if (id != -1L) connection.sendText(CdpMessages.createRpcSuccess(id))
                }

                "Fetch.fulfillRequest" -> {
                    val requestId = params.getString("requestId")
                    val code = params.optInt("responseCode", 200)
                    val rawBody = params.optString("body", "")
                    val isBase64 = params.optBoolean("bodyIsBase64", true)

                    val body = if (isBase64 && rawBody.isNotEmpty()) {
                        NetworkUtils.decodeBase64(rawBody)
                    } else {
                        rawBody
                    }

                    val headersMap = mutableMapOf<String, String>()
                    if (params.has("responseHeaders")) {
                        val hArray = params.getJSONArray("responseHeaders")
                        for (i in 0 until hArray.length()) {
                            val hObj = hArray.getJSONObject(i)
                            headersMap[hObj.getString("name")] = hObj.getString("value")
                        }
                    } else {
                        headersMap["Content-Type"] = "application/json"
                    }
                    headersMap["X-Mocked-By"] = "CDP-Fetch"

                    engine.fulfill(requestId, MockDecision.Fulfill(code, headersMap, body))
                    if (id != -1L) connection.sendText(CdpMessages.createRpcSuccess(id))
                }

                "Fetch.continueRequest" -> {
                    val requestId = params.getString("requestId")
                    engine.continueRequest(requestId)
                    if (id != -1L) connection.sendText(CdpMessages.createRpcSuccess(id))
                }

                "Fetch.failRequest" -> {
                    val requestId = params.getString("requestId")
                    val reason = params.optString("errorReason", "Failed")
                    engine.failRequest(requestId, reason)
                    if (id != -1L) connection.sendText(CdpMessages.createRpcSuccess(id))
                }

                // Chrome DevTools / Puppeteer handshake compatibility stubs
                "Network.enable", "Page.enable", "Runtime.enable", "Log.enable", "DOM.enable" -> {
                    if (id != -1L) connection.sendText(CdpMessages.createRpcSuccess(id))
                }

                else -> {
                    // Unknown method fallback to success for CDP compatibility
                    if (id != -1L) connection.sendText(CdpMessages.createRpcSuccess(id))
                }
            }
        } catch (e: Exception) {
            // Malformed message
        }
    }
}

package io.github.mucker.server

import android.content.Context
import io.github.mucker.core.MockEngine
import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.OutputStream
import java.net.ServerSocket
import java.net.Socket
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import java.util.concurrent.CopyOnWriteArrayList
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors

/**
 * Route plugin interface allowing optional modules (e.g. :mucker-mcp) to handle custom HTTP endpoints.
 */
fun interface HttpRoutePlugin {
    fun handle(
        method: String,
        uri: String,
        cleanPath: String,
        headers: Map<String, String>,
        body: String,
        socket: Socket,
        outStream: OutputStream
    ): Boolean
}

/**
 * Extended plugin interface with lifecycle notifications.
 */
interface MuckerServerPlugin : HttpRoutePlugin {
    fun onServerStop() {}
}

/**
 * Lightweight, zero-dependency HTTP & WebSocket server running inside the Android application.
 */
class MuckerHttpServer(
    val port: Int = 8080,
    private val engine: MockEngine,
    private val context: Context?
) {
    private var serverSocket: ServerSocket? = null
    @Volatile private var isRunning = false
    private val executor: ExecutorService = Executors.newCachedThreadPool()
    private val activeWebSockets = CopyOnWriteArrayList<WebSocketConnection>()
    private val cdpHandler = CdpHandler(engine)
    private val restHandler = RestHandler(engine, port, context)
    val plugins = CopyOnWriteArrayList<HttpRoutePlugin>()

    init {
        // Wire engine broadcast to all active WebSocket clients
        engine.eventBroadcaster = { jsonString ->
            broadcastWebSocket(jsonString)
        }
    }

    fun registerPlugin(plugin: HttpRoutePlugin) {
        plugins.add(plugin)
    }

    fun unregisterPlugin(plugin: HttpRoutePlugin) {
        plugins.remove(plugin)
    }

    @Synchronized
    fun start() {
        if (isRunning) return
        isRunning = true

        try {
            serverSocket = ServerSocket(port)
            serverSocket?.reuseAddress = true

            executor.execute {
                while (isRunning && serverSocket != null && !serverSocket!!.isClosed) {
                    try {
                        val clientSocket = serverSocket!!.accept()
                        executor.execute {
                            handleClient(clientSocket)
                        }
                    } catch (_: Exception) {
                        // socket closed on stop
                    }
                }
            }
        } catch (e: Exception) {
            isRunning = false
        }
    }

    @Synchronized
    fun stop() {
        if (!isRunning) return
        isRunning = false
        try {
            plugins.forEach { (it as? MuckerServerPlugin)?.onServerStop() }
            activeWebSockets.forEach { it.close() }
            activeWebSockets.clear()
            serverSocket?.close()
            serverSocket = null
        } catch (_: Exception) {}
    }

    private fun broadcastWebSocket(text: String) {
        activeWebSockets.forEach { ws ->
            if (!ws.isClosed) {
                ws.sendText(text)
            }
        }
    }

    private fun handleClient(socket: Socket) {
        try {
            val inReader = BufferedReader(InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8))
            val initialLine = inReader.readLine() ?: return
            val parts = initialLine.split(" ")
            if (parts.size < 2) return

            val method = parts[0].uppercase()
            val uri = parts[1]

            val headers = mutableMapOf<String, String>()
            var line: String?
            while (inReader.readLine().also { line = it } != null) {
                if (line.isNullOrEmpty()) break
                val colonIdx = line!!.indexOf(':')
                if (colonIdx > 0) {
                    val key = line!!.substring(0, colonIdx).trim().lowercase()
                    val value = line!!.substring(colonIdx + 1).trim()
                    headers[key] = value
                }
            }

            // Check WebSocket Upgrade
            val isWsUpgrade = headers["upgrade"]?.equals("websocket", ignoreCase = true) == true
            if (isWsUpgrade && uri.startsWith("/devtools/page")) {
                handleWebSocketHandshake(socket, headers)
                return
            }

            val outStream = socket.getOutputStream()

            // Handle CORS Preflight
            if (method == "OPTIONS") {
                sendCorsPreflight(outStream)
                socket.close()
                return
            }

            // Read request body if present
            var body = ""
            val contentLength = headers["content-length"]?.toIntOrNull() ?: 0
            if (contentLength > 0) {
                val charBuf = CharArray(contentLength)
                var readTotal = 0
                while (readTotal < contentLength) {
                    val r = inReader.read(charBuf, readTotal, contentLength - readTotal)
                    if (r == -1) break
                    readTotal += r
                }
                body = String(charBuf, 0, readTotal)
            }

            val cleanPath = uri.split("?")[0].trimEnd('/')

            // Dispatch to registered plugins (e.g. :mucker-mcp)
            for (plugin in plugins) {
                if (plugin.handle(method, uri, cleanPath, headers, body, socket, outStream)) {
                    return
                }
            }

            // Serve Dashboard Web Assets
            if (method == "GET" && (cleanPath == "" || cleanPath == "/index.html")) {
                serveDashboardAsset(outStream)
                socket.close()
                return
            }

            // Route to REST Handler
            val response = restHandler.handle(method, uri, body)
            sendHttpResponse(outStream, response.statusCode, response.contentType, response.body)
            socket.close()

        } catch (_: Exception) {
            try { socket.close() } catch (_: Exception) {}
        }
    }

    private fun handleWebSocketHandshake(socket: Socket, headers: Map<String, String>) {
        val key = headers["sec-websocket-key"] ?: return
        val acceptKey = computeWebSocketAccept(key)

        val out = socket.getOutputStream()
        val response = "HTTP/1.1 101 Switching Protocols\r\n" +
                "Upgrade: websocket\r\n" +
                "Connection: Upgrade\r\n" +
                "Sec-WebSocket-Accept: $acceptKey\r\n\r\n"

        out.write(response.toByteArray(StandardCharsets.UTF_8))
        out.flush()

        val ws = WebSocketConnection(
            socket = socket,
            onMessage = { msg, connection ->
                cdpHandler.handleMessage(msg, connection)
            },
            onClose = { connection ->
                activeWebSockets.remove(connection)
            }
        )

        activeWebSockets.add(ws)
        ws.startListening()
    }

    private fun computeWebSocketAccept(key: String): String {
        val magic = key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
        val md = MessageDigest.getInstance("SHA-1")
        val hash = md.digest(magic.toByteArray(StandardCharsets.UTF_8))
        return java.util.Base64.getEncoder().encodeToString(hash)
    }

    private fun serveDashboardAsset(out: OutputStream) {
        try {
            var html = ""
            if (context != null) {
                try {
                    context.assets.open("mucker-web/index.html").use { input ->
                        html = input.bufferedReader(StandardCharsets.UTF_8).readText()
                    }
                } catch (_: Exception) {}
            }

            if (html.isEmpty()) {
                html = "<html><body><h2>Mucker Engine Running</h2><p>Dashboard asset not found in bundle.</p></body></html>"
            }

            sendHttpResponse(out, 200, "text/html; charset=utf-8", html)
        } catch (_: Exception) {
            sendHttpResponse(out, 500, "text/plain", "Failed to load dashboard")
        }
    }

    fun sendResponse(out: OutputStream, statusCode: Int, contentType: String, body: String) {
        sendHttpResponse(out, statusCode, contentType, body)
    }

    fun sendPreflight(out: OutputStream) {
        sendCorsPreflight(out)
    }

    private fun sendHttpResponse(out: OutputStream, statusCode: Int, contentType: String, body: String) {
        val bodyBytes = body.toByteArray(StandardCharsets.UTF_8)
        val statusText = when (statusCode) {
            200 -> "OK"
            202 -> "Accepted"
            204 -> "No Content"
            400 -> "Bad Request"
            404 -> "Not Found"
            500 -> "Internal Server Error"
            else -> "OK"
        }
        val header = "HTTP/1.1 $statusCode $statusText\r\n" +
                "Content-Type: $contentType\r\n" +
                "Content-Length: ${bodyBytes.size}\r\n" +
                "Access-Control-Allow-Origin: *\r\n" +
                "Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS\r\n" +
                "Access-Control-Allow-Headers: *\r\n" +
                "Connection: close\r\n\r\n"

        out.write(header.toByteArray(StandardCharsets.UTF_8))
        out.write(bodyBytes)
        out.flush()
    }

    private fun sendCorsPreflight(out: OutputStream) {
        val header = "HTTP/1.1 204 No Content\r\n" +
                "Access-Control-Allow-Origin: *\r\n" +
                "Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS\r\n" +
                "Access-Control-Allow-Headers: *\r\n" +
                "Access-Control-Max-Age: 86400\r\n" +
                "Content-Length: 0\r\n" +
                "Connection: close\r\n\r\n"
        out.write(header.toByteArray(StandardCharsets.UTF_8))
        out.flush()
    }
}

package io.github.mucker

import io.github.mucker.core.MockEngine
import io.github.mucker.core.models.CdpMessages
import io.github.mucker.core.models.MockDecision
import io.github.mucker.core.models.NetworkRecord
import okhttp3.Interceptor
import okhttp3.MediaType.Companion.toMediaTypeOrNull
import okhttp3.Protocol
import okhttp3.Response
import okhttp3.ResponseBody.Companion.toResponseBody
import okio.Buffer
import java.io.IOException
import java.nio.charset.StandardCharsets
import java.util.UUID
import java.util.concurrent.TimeUnit
import java.util.concurrent.TimeoutException

/**
 * OkHttp Interceptor that logs network requests and dynamically injects mock responses or breakpoints.
 */
class MuckerInterceptor(
    private val engine: MockEngine = Mucker.engine,
    private val timeoutSeconds: Long = 25L
) : Interceptor {

    override fun intercept(chain: Interceptor.Chain): Response {
        val request = chain.request()
        val url = request.url.toString()
        val method = request.method
        val requestId = "req_" + UUID.randomUUID().toString().take(8)

        // Read request headers
        val requestHeaders = mutableMapOf<String, String>()
        for (i in 0 until request.headers.size) {
            requestHeaders[request.headers.name(i)] = request.headers.value(i)
        }

        // Read request payload if present
        var postData: String? = null
        try {
            request.body?.let { body ->
                val buffer = Buffer()
                body.writeTo(buffer)
                postData = buffer.readString(StandardCharsets.UTF_8)
            }
        } catch (_: Exception) {}

        val record = NetworkRecord(
            id = requestId,
            url = url,
            method = method,
            headers = requestHeaders,
            postData = postData
        )
        engine.history.record(record)

        // Broadcast CDP Network.requestWillBeSent
        engine.broadcast(CdpMessages.createNetworkRequestWillBeSent(requestId, url, method, requestHeaders))

        // 1. Check static mock rules
        val matchedRule = engine.rules.findMatchingRule(method, url)
        if (matchedRule != null && matchedRule.isEnabled) {
            if (matchedRule.delayMs > 0) {
                try {
                    Thread.sleep(matchedRule.delayMs)
                } catch (_: InterruptedException) {}
            }

            val mockResponse = buildMockResponse(
                chain = chain,
                statusCode = matchedRule.statusCode,
                headers = matchedRule.responseHeaders,
                body = matchedRule.responseBody,
                mockTag = "Mucker-Rule"
            )

            record.statusCode = matchedRule.statusCode
            record.responseHeaders = matchedRule.responseHeaders
            record.responseBody = matchedRule.responseBody
            record.responseTime = matchedRule.delayMs
            record.isMocked = true

            engine.broadcast(
                CdpMessages.createNetworkResponseReceived(
                    requestId = requestId,
                    url = url,
                    status = matchedRule.statusCode,
                    headers = matchedRule.responseHeaders,
                    body = matchedRule.responseBody,
                    responseTime = matchedRule.delayMs
                )
            )

            return mockResponse
        }

        // 2. Check Breakpoint Mode
        if (engine.shouldIntercept(url)) {
            val future = engine.pauseRequest(record)
            val decision = try {
                future.get(timeoutSeconds, TimeUnit.SECONDS)
            } catch (e: TimeoutException) {
                // Safe timeout fallback so app never hangs
                MockDecision.Continue
            } catch (e: Exception) {
                MockDecision.Continue
            }

            when (decision) {
                is MockDecision.Fulfill -> {
                    val mockResponse = buildMockResponse(
                        chain = chain,
                        statusCode = decision.statusCode,
                        headers = decision.headers,
                        body = decision.body,
                        mockTag = "Mucker-Breakpoint"
                    )

                    record.isPaused = false
                    record.isMocked = true
                    record.statusCode = decision.statusCode
                    record.responseHeaders = decision.headers
                    record.responseBody = decision.body
                    record.responseTime = 0

                    engine.broadcast(
                        CdpMessages.createNetworkResponseReceived(
                            requestId = requestId,
                            url = url,
                            status = decision.statusCode,
                            headers = decision.headers,
                            body = decision.body
                        )
                    )

                    return mockResponse
                }
                is MockDecision.Fail -> {
                    record.isPaused = false
                    record.error = decision.errorReason
                    throw IOException("Blocked by Mucker Breakpoint: ${decision.errorReason}")
                }
                is MockDecision.Continue -> {
                    record.isPaused = false
                    // Fallthrough to chain.proceed below
                }
            }
        }

        // 3. Normal real network execution
        val startNs = System.nanoTime()
        val response: Response
        try {
            response = chain.proceed(request)
        } catch (e: Exception) {
            record.error = e.message ?: "Network error"
            throw e
        }
        val tookMs = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startNs)

        // Read response headers
        val responseHeaders = mutableMapOf<String, String>()
        for (i in 0 until response.headers.size) {
            responseHeaders[response.headers.name(i)] = response.headers.value(i)
        }

        // Peek response body safely for inspection (up to 1MB)
        var responseBodyString: String? = null
        try {
            response.peekBody(1024 * 1024).let { peeked ->
                responseBodyString = peeked.string()
            }
        } catch (_: Exception) {}

        record.statusCode = response.code
        record.responseHeaders = responseHeaders
        record.responseBody = responseBodyString
        record.responseTime = tookMs
        record.isMocked = false

        engine.broadcast(
            CdpMessages.createNetworkResponseReceived(
                requestId = requestId,
                url = url,
                status = response.code,
                headers = responseHeaders,
                body = responseBodyString,
                responseTime = tookMs
            )
        )

        return response
    }

    private fun buildMockResponse(
        chain: Interceptor.Chain,
        statusCode: Int,
        headers: Map<String, String>,
        body: String,
        mockTag: String
    ): Response {
        val mediaType = (headers["Content-Type"] ?: "application/json; charset=utf-8").toMediaTypeOrNull()
        val responseBody = body.toResponseBody(mediaType)

        val builder = Response.Builder()
            .request(chain.request())
            .protocol(Protocol.HTTP_1_1)
            .code(statusCode)
            .message("Mocked by $mockTag")
            .body(responseBody)
            .addHeader("X-Mocked-By", mockTag)

        headers.forEach { (name, value) ->
            if (!name.equals("X-Mocked-By", ignoreCase = true)) {
                builder.addHeader(name, value)
            }
        }

        return builder.build()
    }
}

package io.github.mucker

import android.annotation.SuppressLint
import android.content.Context
import io.github.mucker.core.MockEngine
import io.github.mucker.core.MockRuleRegistry
import io.github.mucker.core.RequestHistory
import io.github.mucker.server.MuckerHttpServer
import io.github.mucker.util.NetworkUtils

/**
 * Main entry point for Mucker CDP-compatible In-App Mock Engine.
 */
@SuppressLint("StaticFieldLeak")
object Mucker {

    @Volatile private var appContext: Context? = null
    @Volatile private var server: MuckerHttpServer? = null

    val engine = MockEngine(
        rules = MockRuleRegistry(),
        history = RequestHistory(maxSize = 250)
    )

    val rules: MockRuleRegistry
        get() = engine.rules

    val history: RequestHistory
        get() = engine.history

    var port: Int = 8080
        private set

    val interceptor: MuckerInterceptor by lazy {
        MuckerInterceptor(engine)
    }

    val serverUrl: String
        get() {
            val ip = NetworkUtils.getLocalIpAddress(appContext)
            return "http://$ip:$port"
        }

    @Synchronized
    fun install(context: Context, config: MuckerConfig = MuckerConfig()) {
        if (appContext != null) return
        appContext = context.applicationContext
        port = config.port

        engine.breakpointMode = config.breakpointMode

        if (config.autoStart) {
            start()
        }

        if (config.showNotification) {
            triggerNotificationShow(context, serverUrl)
        }
    }

    val currentServer: MuckerHttpServer?
        get() = server

    @Synchronized
    fun start() {
        val ctx = appContext
        if (server == null) {
            val s = MuckerHttpServer(port = port, engine = engine, context = ctx)
            server = s
            triggerMcpInit(s)
        }
        server?.start()
    }

    @Synchronized
    fun stop() {
        server?.stop()
        server = null
        appContext?.let { triggerNotificationHide(it) }
    }

    private fun triggerMcpInit(server: MuckerHttpServer) {
        try {
            val clazz = Class.forName("io.github.mucker.mcp.MuckerMcp")
            val method = clazz.getMethod("install", MuckerHttpServer::class.java, MockEngine::class.java, Context::class.java)
            method.invoke(null, server, engine, appContext)
        } catch (_: Throwable) {
            // Headless / Core mode: MCP module not on classpath
        }
    }

    private fun triggerNotificationShow(context: Context, url: String) {
        try {
            val clazz = Class.forName("io.github.mucker.ui.MuckerNotification")
            val method = clazz.getMethod("show", Context::class.java, String::class.java)
            method.invoke(null, context, url)
        } catch (_: Throwable) {
            // Headless mode: no notification UI available on classpath
        }
    }

    private fun triggerNotificationHide(context: Context) {
        try {
            val clazz = Class.forName("io.github.mucker.ui.MuckerNotification")
            val method = clazz.getMethod("hide", Context::class.java)
            method.invoke(null, context)
        } catch (_: Throwable) {
            // Headless mode
        }
    }
}

package io.github.mucker.core

import io.github.mucker.core.models.CdpMessages
import io.github.mucker.core.models.MockDecision
import io.github.mucker.core.models.NetworkRecord
import java.util.concurrent.CompletableFuture
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.CopyOnWriteArrayList

/**
 * Orchestrates mock rules, breakpoints, and CDP event dispatching.
 */
class MockEngine(
    val rules: MockRuleRegistry = MockRuleRegistry(),
    val history: RequestHistory = RequestHistory()
) {
    var breakpointMode: Boolean = false
    private val interceptPatterns = CopyOnWriteArrayList<String>()
    private val pendingFutures = ConcurrentHashMap<String, CompletableFuture<MockDecision>>()

    var eventBroadcaster: ((String) -> Unit)? = null

    fun enableInterception(patterns: List<String>) {
        breakpointMode = true
        interceptPatterns.clear()
        interceptPatterns.addAll(patterns)
    }

    fun disableInterception() {
        breakpointMode = false
        interceptPatterns.clear()
        // Resume any pending futures so thread is never leaked
        pendingFutures.forEach { (_, future) ->
            future.complete(MockDecision.Continue)
        }
        pendingFutures.clear()
    }

    fun shouldIntercept(url: String): Boolean {
        if (!breakpointMode) return false
        if (interceptPatterns.isEmpty()) return true // default intercept all if pattern is empty

        return interceptPatterns.any { pattern ->
            if (pattern == "*") true
            else try {
                val regexPattern = pattern.replace(".", "\\.").replace("*", ".*")
                url.matches(Regex(regexPattern)) || url.contains(pattern)
            } catch (_: Exception) {
                url.contains(pattern)
            }
        }
    }

    /**
     * Pauses the request thread and broadcasts Fetch.requestPaused to all connected CDP clients / web UI.
     */
    fun pauseRequest(record: NetworkRecord): CompletableFuture<MockDecision> {
        val future = CompletableFuture<MockDecision>()
        pendingFutures[record.id] = future
        record.isPaused = true

        // Broadcast CDP Fetch.requestPaused
        val eventJson = CdpMessages.createFetchRequestPaused(
            requestId = record.id,
            url = record.url,
            method = record.method,
            headers = record.headers,
            postData = record.postData
        )
        eventBroadcaster?.invoke(eventJson)

        return future
    }

    fun fulfill(requestId: String, decision: MockDecision.Fulfill): Boolean {
        val future = pendingFutures.remove(requestId) ?: return false
        val rec = history.find(requestId)
        if (rec != null) {
            rec.isPaused = false
            rec.isMocked = true
            rec.statusCode = decision.statusCode
            rec.responseHeaders = decision.headers
            rec.responseBody = decision.body
        }
        future.complete(decision)
        return true
    }

    fun continueRequest(requestId: String): Boolean {
        val future = pendingFutures.remove(requestId) ?: return false
        val rec = history.find(requestId)
        if (rec != null) {
            rec.isPaused = false
        }
        future.complete(MockDecision.Continue)
        return true
    }

    fun failRequest(requestId: String, reason: String = "Failed"): Boolean {
        val future = pendingFutures.remove(requestId) ?: return false
        val rec = history.find(requestId)
        if (rec != null) {
            rec.isPaused = false
            rec.error = reason
        }
        future.complete(MockDecision.Fail(reason))
        return true
    }

    fun getPendingPausedCount(): Int = pendingFutures.size

    fun broadcast(json: String) {
        eventBroadcaster?.invoke(json)
    }
}

package io.github.mucker.core

import io.github.mucker.core.models.NetworkRecord
import org.json.JSONArray
import java.util.concurrent.CopyOnWriteArrayList

/**
 * Thread-safe ring buffer storing recent network inspections.
 */
class RequestHistory(private val maxSize: Int = 200) {

    private val records = CopyOnWriteArrayList<NetworkRecord>()

    fun record(record: NetworkRecord) {
        records.add(0, record)
        while (records.size > maxSize) {
            records.removeAt(records.lastIndex)
        }
    }

    fun find(id: String): NetworkRecord? {
        return records.firstOrNull { it.id == id }
    }

    fun getAll(): List<NetworkRecord> {
        return records.toList()
    }

    fun clear() {
        records.clear()
    }

    fun toJson(): JSONArray {
        val array = JSONArray()
        records.forEach { array.put(it.toJson()) }
        return array
    }
}

package io.github.mucker.core

import io.github.mucker.core.models.MockRule
import org.json.JSONArray
import java.util.concurrent.CopyOnWriteArrayList

/**
 * Thread-safe registry for configured mock rules.
 */
class MockRuleRegistry {

    private val rules = CopyOnWriteArrayList<MockRule>()

    fun addRule(rule: MockRule): MockRule {
        // If rule with same ID exists, replace it
        val existingIndex = rules.indexOfFirst { it.id == rule.id }
        if (existingIndex >= 0) {
            rules[existingIndex] = rule
        } else {
            rules.add(rule)
        }
        return rule
    }

    fun removeRule(ruleId: String): Boolean {
        return rules.removeIf { it.id == ruleId }
    }

    fun clearRules() {
        rules.clear()
    }

    fun toggleRule(ruleId: String, isEnabled: Boolean): Boolean {
        val rule = rules.firstOrNull { it.id == ruleId } ?: return false
        rule.isEnabled = isEnabled
        return true
    }

    fun findMatchingRule(method: String, url: String): MockRule? {
        return rules.firstOrNull { it.matches(method, url) }
    }

    fun getAllRules(): List<MockRule> {
        return rules.toList()
    }

    fun toJson(): JSONArray {
        val array = JSONArray()
        rules.forEach { array.put(it.toJson()) }
        return array
    }

    fun loadFromJson(jsonArray: JSONArray) {
        rules.clear()
        for (i in 0 until jsonArray.length()) {
            val obj = jsonArray.getJSONObject(i)
            rules.add(MockRule.fromJson(obj))
        }
    }
}

package io.github.mucker.util

import android.content.Context
import android.net.wifi.WifiManager
import java.net.Inet4Address
import java.net.NetworkInterface
import java.nio.charset.StandardCharsets
import java.util.Base64

object NetworkUtils {

    /**
     * Resolves the primary local IPv4 address (e.g. Wi-Fi IP or hotspot IP).
     */
    fun getLocalIpAddress(context: Context? = null): String {
        try {
            val interfaces = NetworkInterface.getNetworkInterfaces()
            while (interfaces.hasMoreElements()) {
                val iface = interfaces.nextElement()
                if (iface.isLoopback || !iface.isUp) continue

                val addresses = iface.inetAddresses
                while (addresses.hasMoreElements()) {
                    val addr = addresses.nextElement()
                    if (!addr.isLoopbackAddress && addr is Inet4Address) {
                        val host = addr.hostAddress
                        if (host != null && !host.startsWith("127.")) {
                            return host
                        }
                    }
                }
            }
        } catch (_: Exception) {}

        return "127.0.0.1"
    }

    fun decodeBase64(str: String): String {
        return try {
            val bytes = java.util.Base64.getDecoder().decode(str)
            String(bytes, StandardCharsets.UTF_8)
        } catch (_: Throwable) {
            try {
                val bytes = android.util.Base64.decode(str, android.util.Base64.DEFAULT)
                String(bytes, StandardCharsets.UTF_8)
            } catch (_: Throwable) {
                str
            }
        }
    }

    fun encodeBase64(str: String): String {
        return try {
            java.util.Base64.getEncoder().encodeToString(str.toByteArray(StandardCharsets.UTF_8))
        } catch (_: Throwable) {
            try {
                android.util.Base64.encodeToString(str.toByteArray(StandardCharsets.UTF_8), android.util.Base64.NO_WRAP)
            } catch (_: Throwable) {
                str
            }
        }
    }
}

