package io.github.mucker.mcp

import android.content.Context
import io.github.mucker.core.MockEngine
import io.github.mucker.core.models.MockDecision
import io.github.mucker.core.models.MockRule
import org.json.JSONArray
import org.json.JSONObject
import java.util.UUID

/**
 * Handles Model Context Protocol (MCP) JSON-RPC 2.0 messages over Streamable HTTP and SSE.
 * Allows AI assistants (Claude Code, Cursor, Windsurf, local LLMs) to directly control
 * the in-app OkHttp mock engine running on the Android device or emulator.
 */
class McpHandler(
    private val engine: MockEngine,
    private val port: Int,
    private val context: Context?
) {

    /**
     * Handles an incoming MCP JSON-RPC message and returns the JSON-RPC response.
     */
    fun handleMessage(rawMessage: String): String {
        return try {
            val trimmed = rawMessage.trim()
            if (trimmed.isEmpty()) return createError(null, -32700, "Empty payload")
            if (trimmed.startsWith("[")) {
                // Batch request
                val array = JSONArray(trimmed)
                val results = JSONArray()
                for (i in 0 until array.length()) {
                    val item = array.getJSONObject(i)
                    val res = processSingleRequest(item)
                    if (res != null) results.put(JSONObject(res))
                }
                results.toString()
            } else {
                val json = JSONObject(trimmed)
                processSingleRequest(json) ?: ""
            }
        } catch (e: Exception) {
            createError(null, -32700, "Parse error: ${e.message}")
        }
    }

    private fun processSingleRequest(json: JSONObject): String? {
        val id = if (json.has("id")) json.get("id") else null
        val method = json.optString("method", "")
        val params = json.optJSONObject("params") ?: JSONObject()

        return when (method) {
            "initialize" -> handleInitialize(id, params)
            "notifications/initialized" -> {
                // Client acknowledgement, no response required if notification (id == null)
                if (id != null) createResult(id, JSONObject()) else null
            }
            "ping" -> createResult(id, JSONObject())
            "tools/list" -> handleToolsList(id)
            "tools/call" -> handleToolsCall(id, params)
            else -> createError(id, -32601, "Method not found: $method")
        }
    }

    @Suppress("UNUSED_PARAMETER")
    private fun handleInitialize(id: Any?, params: JSONObject): String {
        val result = JSONObject()
        result.put("protocolVersion", "2024-11-05")

        val capabilities = JSONObject()
        val toolsCap = JSONObject()
        toolsCap.put("listChanged", false)
        capabilities.put("tools", toolsCap)
        result.put("capabilities", capabilities)

        val serverInfo = JSONObject()
        serverInfo.put("name", "mucker-android-interceptor")
        serverInfo.put("version", "1.0.0")
        result.put("serverInfo", serverInfo)

        return createResult(id, result)
    }

    private fun handleToolsList(id: Any?): String {
        val toolsArray = JSONArray()

        toolsArray.put(createToolDefinition(
            name = "get_status",
            description = "Get live Mucker server status, active mock rules count, breakpoint mode state, and pending requests.",
            inputProperties = mapOf()
        ))

        toolsArray.put(createToolDefinition(
            name = "list_rules",
            description = "List all registered mock rules currently active in Mucker memory.",
            inputProperties = mapOf()
        ))

        toolsArray.put(createToolDefinition(
            name = "add_rule",
            description = "Add or update a dynamic mock rule with custom URL pattern, method, HTTP status code, delay, and response body.",
            inputProperties = mapOf(
                "urlPattern" to mapOf("type" to "string", "description" to "Regex or substring URL pattern to match, e.g. .*/api/v1/user.*"),
                "method" to mapOf("type" to "string", "description" to "HTTP Method (GET, POST, PUT, DELETE, or ALL). Default: ALL"),
                "statusCode" to mapOf("type" to "integer", "description" to "HTTP Status code to return (e.g. 200, 404, 500). Default: 200"),
                "delayMs" to mapOf("type" to "integer", "description" to "Simulated network latency in milliseconds. Default: 0"),
                "responseBody" to mapOf("type" to "string", "description" to "JSON response body string. Default: {\"mocked\":true}")
            ),
            required = listOf("urlPattern")
        ))

        toolsArray.put(createToolDefinition(
            name = "remove_rule",
            description = "Delete a mock rule by its unique ID from Mucker memory.",
            inputProperties = mapOf(
                "id" to mapOf("type" to "string", "description" to "The rule ID to delete")
            ),
            required = listOf("id")
        ))

        toolsArray.put(createToolDefinition(
            name = "clear_rules",
            description = "Clear all mock rules from Mucker engine memory.",
            inputProperties = mapOf()
        ))

        toolsArray.put(createToolDefinition(
            name = "toggle_rule",
            description = "Enable or disable a mock rule without deleting it.",
            inputProperties = mapOf(
                "id" to mapOf("type" to "string", "description" to "The rule ID to toggle"),
                "isEnabled" to mapOf("type" to "boolean", "description" to "true to enable, false to disable")
            ),
            required = listOf("id", "isEnabled")
        ))

        toolsArray.put(createToolDefinition(
            name = "set_breakpoint_mode",
            description = "Toggle global breakpoint interception on or off. When enabled, matching requests pause in-flight.",
            inputProperties = mapOf(
                "breakpointMode" to mapOf("type" to "boolean", "description" to "true to enable global request pausing, false to disable")
            ),
            required = listOf("breakpointMode")
        ))

        toolsArray.put(createToolDefinition(
            name = "list_history",
            description = "Query recorded network request history with optional URL/body search filter.",
            inputProperties = mapOf(
                "query" to mapOf("type" to "string", "description" to "Search keyword in request URL or response body"),
                "method" to mapOf("type" to "string", "description" to "Filter by HTTP method (GET, POST, etc.)"),
                "limit" to mapOf("type" to "integer", "description" to "Maximum number of records to return. Default: 20")
            )
        ))

        toolsArray.put(createToolDefinition(
            name = "fulfill_request",
            description = "Fulfill an in-flight paused OkHttp request with a mocked status code, response headers, and response body.",
            inputProperties = mapOf(
                "requestId" to mapOf("type" to "string", "description" to "The paused request ID (e.g. req_12345)"),
                "statusCode" to mapOf("type" to "integer", "description" to "HTTP status code. Default: 200"),
                "responseBody" to mapOf("type" to "string", "description" to "Mocked response body string")
            ),
            required = listOf("requestId")
        ))

        toolsArray.put(createToolDefinition(
            name = "continue_request",
            description = "Resume a paused OkHttp request to hit the real network without modification.",
            inputProperties = mapOf(
                "requestId" to mapOf("type" to "string", "description" to "The paused request ID to continue")
            ),
            required = listOf("requestId")
        ))

        toolsArray.put(createToolDefinition(
            name = "get_mock_rule_template",
            description = "Generate a ready-to-run curl or REST API payload template for Mucker.",
            inputProperties = mapOf(
                "urlPattern" to mapOf("type" to "string", "description" to "Target URL pattern"),
                "statusCode" to mapOf("type" to "integer", "description" to "Status code. Default: 200"),
                "responseBody" to mapOf("type" to "string", "description" to "Sample response body")
            ),
            required = listOf("urlPattern")
        ))

        val result = JSONObject()
        result.put("tools", toolsArray)
        return createResult(id, result)
    }

    private fun handleToolsCall(id: Any?, params: JSONObject): String {
        val name = params.optString("name", "")
        val args = params.optJSONObject("arguments") ?: JSONObject()

        return try {
            val contentText = when (name) {
                "get_status" -> {
                    val status = JSONObject()
                    status.put("status", "running")
                    status.put("port", port)
                    status.put("app", context?.packageName ?: "Android App")
                    status.put("breakpointMode", engine.breakpointMode)
                    status.put("activeRulesCount", engine.rules.getAllRules().size)
                    status.put("pausedRequestsCount", engine.getPendingPausedCount())
                    status.put("totalHistoryCount", engine.history.getAll().size)
                    status.toString(2)
                }

                "list_rules" -> {
                    engine.rules.toJson().toString(2)
                }

                "add_rule" -> {
                    val urlPattern = args.getString("urlPattern")
                    val method = args.optString("method", "ALL")
                    val statusCode = args.optInt("statusCode", 200)
                    val delayMs = args.optLong("delayMs", 0)
                    val responseBody = args.optString("responseBody", "{\"mocked\":true}")

                    val rule = MockRule(
                        id = UUID.randomUUID().toString().take(8),
                        urlPattern = urlPattern,
                        method = method,
                        statusCode = statusCode,
                        delayMs = delayMs,
                        responseHeaders = mapOf("Content-Type" to "application/json", "X-Mocked-By" to "Mucker-InApp-MCP"),
                        responseBody = responseBody,
                        isEnabled = true
                    )
                    engine.rules.addRule(rule)
                    "Successfully created mock rule:\n${rule.toJson().toString(2)}"
                }

                "remove_rule" -> {
                    val ruleId = args.getString("id")
                    val ok = engine.rules.removeRule(ruleId)
                    if (ok) "Successfully removed mock rule: $ruleId" else "Rule not found: $ruleId"
                }

                "clear_rules" -> {
                    val count = engine.rules.getAllRules().size
                    engine.rules.clearRules()
                    "Cleared all $count mock rules from Mucker engine memory."
                }

                "toggle_rule" -> {
                    val ruleId = args.getString("id")
                    val isEnabled = args.getBoolean("isEnabled")
                    val ok = engine.rules.toggleRule(ruleId, isEnabled)
                    if (ok) "Rule $ruleId is now ${if (isEnabled) "ENABLED" else "DISABLED"}" else "Rule not found: $ruleId"
                }

                "set_breakpoint_mode" -> {
                    val mode = args.getBoolean("breakpointMode")
                    engine.breakpointMode = mode
                    "Breakpoint mode is now ${if (mode) "ENABLED (all matching requests will pause)" else "DISABLED"}."
                }

                "list_history" -> {
                    val query = args.optString("query", "").lowercase()
                    val method = args.optString("method", "").uppercase()
                    val limit = args.optInt("limit", 20)

                    val records = engine.history.getAll().filter { rec ->
                        (method.isEmpty() || rec.method.equals(method, ignoreCase = true)) &&
                        (query.isEmpty() || rec.url.lowercase().contains(query) || (rec.responseBody?.lowercase()?.contains(query) == true))
                    }.take(limit)

                    val arr = JSONArray()
                    for (rec in records) {
                        arr.put(rec.toJson())
                    }
                    arr.toString(2)
                }

                "fulfill_request" -> {
                    val requestId = args.getString("requestId")
                    val statusCode = args.optInt("statusCode", 200)
                    val responseBody = args.optString("responseBody", "{\"status\":\"fulfilled_via_mcp\"}")
                    val headersMap = mapOf("Content-Type" to "application/json", "X-Mocked-By" to "Mucker-InApp-MCP")

                    val ok = engine.fulfill(requestId, MockDecision.Fulfill(statusCode, headersMap, responseBody))
                    if (ok) "Successfully fulfilled paused request $requestId with status $statusCode." else "Failed to fulfill: request $requestId not found or timed out."
                }

                "continue_request" -> {
                    val requestId = args.getString("requestId")
                    val ok = engine.continueRequest(requestId)
                    if (ok) "Successfully resumed request $requestId to real network." else "Failed: request $requestId not found or timed out."
                }

                "get_mock_rule_template" -> {
                    val urlPattern = args.getString("urlPattern")
                    val statusCode = args.optInt("statusCode", 200)
                    val body = args.optString("responseBody", "{\"status\":\"mocked\"}")
                    val curl = "curl -X POST http://localhost:$port/api/rules -H \"Content-Type: application/json\" -d '{\"urlPattern\":\"$urlPattern\",\"statusCode\":$statusCode,\"responseBody\":${JSONObject.quote(body)}}'"
                    "Mock Rule Template for $urlPattern (HTTP $statusCode):\n\n$curl"
                }

                else -> throw IllegalArgumentException("Unknown tool: $name")
            }

            createToolCallResult(id, contentText, isError = false)
        } catch (e: Exception) {
            createToolCallResult(id, "Error executing $name: ${e.message}", isError = true)
        }
    }

    private fun createToolDefinition(
        name: String,
        description: String,
        inputProperties: Map<String, Map<String, String>>,
        required: List<String> = emptyList()
    ): JSONObject {
        val tool = JSONObject()
        tool.put("name", name)
        tool.put("description", description)

        val schema = JSONObject()
        schema.put("type", "object")

        val props = JSONObject()
        inputProperties.forEach { (key, meta) ->
            val p = JSONObject()
            meta.forEach { (mk, mv) -> p.put(mk, mv) }
            props.put(key, p)
        }
        schema.put("properties", props)

        if (required.isNotEmpty()) {
            val reqArray = JSONArray()
            required.forEach { reqArray.put(it) }
            schema.put("required", reqArray)
        }

        tool.put("inputSchema", schema)
        return tool
    }

    private fun createToolCallResult(id: Any?, text: String, isError: Boolean): String {
        val result = JSONObject()
        val contentArray = JSONArray()
        val contentItem = JSONObject()
        contentItem.put("type", "text")
        contentItem.put("text", text)
        contentArray.put(contentItem)

        result.put("content", contentArray)
        result.put("isError", isError)
        return createResult(id, result)
    }

    private fun createResult(id: Any?, result: JSONObject): String {
        val root = JSONObject()
        root.put("jsonrpc", "2.0")
        if (id != null) root.put("id", id) else root.put("id", JSONObject.NULL)
        root.put("result", result)
        return root.toString()
    }

    private fun createError(id: Any?, code: Int, message: String): String {
        val root = JSONObject()
        root.put("jsonrpc", "2.0")
        if (id != null) root.put("id", id) else root.put("id", JSONObject.NULL)

        val err = JSONObject()
        err.put("code", code)
        err.put("message", message)
        root.put("error", err)
        return root.toString()
    }
}

package io.github.mucker.mcp

import android.content.Context
import io.github.mucker.core.MockEngine
import io.github.mucker.server.MuckerHttpServer
import io.github.mucker.server.MuckerServerPlugin
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.launch
import org.json.JSONArray
import org.json.JSONObject
import java.io.OutputStream
import java.net.Socket
import java.nio.charset.StandardCharsets
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap

/**
 * Idiomatic, Coroutines-powered Model Context Protocol (MCP) server plugin for Mucker.
 * Handles Streamable HTTP (POST /mcp) and Server-Sent Events (GET /sse, POST /message).
 */
class MuckerMcpPlugin(
    private val engine: MockEngine,
    private val port: Int,
    private val context: Context?,
    private val scope: CoroutineScope = CoroutineScope(Dispatchers.IO + SupervisorJob())
) : MuckerServerPlugin {

    val handler = McpHandler(engine, port, context)

    private class SseSession(
        val sessionId: String,
        val socket: Socket,
        val channel: Channel<String>,
        val job: Job
    )

    private val activeSessions = ConcurrentHashMap<String, SseSession>()

    override fun handle(
        method: String,
        uri: String,
        cleanPath: String,
        headers: Map<String, String>,
        body: String,
        socket: Socket,
        outStream: OutputStream
    ): Boolean {
        return when {
            // Streamable HTTP: POST /mcp or POST /api/mcp
            (cleanPath == "/mcp" || cleanPath == "/api/mcp") && method == "POST" -> {
                val response = handler.handleMessage(body)
                sendHttpResponse(outStream, 200, "application/json; charset=utf-8", response)
                socket.close()
                true
            }

            // Discovery: GET /mcp or GET /api/mcp
            (cleanPath == "/mcp" || cleanPath == "/api/mcp") && method == "GET" -> {
                val discovery = JSONObject().apply {
                    put("service", "mucker-mcp-server")
                    put("version", "1.0.0")
                    put("transports", JSONArray(listOf("streamable-http", "sse")))
                    put("endpoints", JSONObject().apply {
                        put("http", "/mcp")
                        put("sse", "/sse")
                        put("message", "/message")
                    })
                }
                sendHttpResponse(outStream, 200, "application/json; charset=utf-8", discovery.toString(2))
                socket.close()
                true
            }

            // SSE Stream: GET /sse or GET /mcp/sse
            (cleanPath == "/sse" || cleanPath == "/mcp/sse") && method == "GET" -> {
                handleSseConnect(socket, outStream)
                true
            }

            // SSE Client Message: POST /message or POST /messages
            (cleanPath == "/message" || cleanPath == "/messages") && method == "POST" -> {
                handleSsePostMessage(uri, body, socket, outStream)
                true
            }

            else -> false
        }
    }

    private fun handleSseConnect(socket: Socket, outStream: OutputStream) {
        val sessionId = UUID.randomUUID().toString()
        val eventChannel = Channel<String>(Channel.BUFFERED)

        val job = scope.launch {
            try {
                // 1. Initial SSE Header
                val header = "HTTP/1.1 200 OK\r\n" +
                        "Content-Type: text/event-stream\r\n" +
                        "Cache-Control: no-cache\r\n" +
                        "Connection: keep-alive\r\n" +
                        "Access-Control-Allow-Origin: *\r\n" +
                        "Access-Control-Allow-Headers: *\r\n\r\n"
                outStream.write(header.toByteArray(StandardCharsets.UTF_8))
                outStream.flush()

                // 2. Announce message POST endpoint with sessionId per MCP SSE spec
                val endpointEvent = "event: endpoint\r\ndata: /message?sessionId=$sessionId\r\n\r\n"
                outStream.write(endpointEvent.toByteArray(StandardCharsets.UTF_8))
                outStream.flush()

                // 3. Consume channel events and push over SSE
                for (msg in eventChannel) {
                    if (socket.isClosed) break
                    val event = "event: message\r\ndata: $msg\r\n\r\n"
                    outStream.write(event.toByteArray(StandardCharsets.UTF_8))
                    outStream.flush()
                }
            } catch (_: Exception) {
            } finally {
                activeSessions.remove(sessionId)
                eventChannel.close()
                try { socket.close() } catch (_: Exception) {}
            }
        }

        val session = SseSession(sessionId, socket, eventChannel, job)
        activeSessions[sessionId] = session

        // Monitor client disconnect in background
        scope.launch {
            try {
                val inStream = socket.getInputStream()
                val buf = ByteArray(128)
                while (!socket.isClosed) {
                    val r = inStream.read(buf)
                    if (r == -1) break
                }
            } catch (_: Exception) {
            } finally {
                session.job.cancel()
                session.channel.close()
                activeSessions.remove(sessionId)
                try { socket.close() } catch (_: Exception) {}
            }
        }
    }

    private fun handleSsePostMessage(uri: String, body: String, socket: Socket, outStream: OutputStream) {
        val sessionId = parseQueryParam(uri, "sessionId")
        val session = sessionId?.let { activeSessions[it] }

        val result = handler.handleMessage(body)

        if (session != null && !session.socket.isClosed) {
            if (result.isNotEmpty()) {
                session.channel.trySend(result)
            }
            sendHttpResponse(outStream, 202, "text/plain; charset=utf-8", "Accepted")
        } else {
            if (result.isNotEmpty()) {
                sendHttpResponse(outStream, 200, "application/json; charset=utf-8", result)
            } else {
                sendHttpResponse(outStream, 204, "text/plain", "")
            }
        }
        socket.close()
    }

    private fun parseQueryParam(uri: String, key: String): String? {
        val qIdx = uri.indexOf('?')
        if (qIdx == -1 || qIdx >= uri.length - 1) return null
        val query = uri.substring(qIdx + 1)
        for (pair in query.split("&")) {
            val parts = pair.split("=", limit = 2)
            if (parts[0] == key) {
                return if (parts.size > 1) parts[1] else ""
            }
        }
        return null
    }

    private fun sendHttpResponse(out: OutputStream, statusCode: Int, contentType: String, body: String) {
        val bodyBytes = body.toByteArray(StandardCharsets.UTF_8)
        val statusText = when (statusCode) {
            200 -> "OK"
            202 -> "Accepted"
            204 -> "No Content"
            400 -> "Bad Request"
            404 -> "Not Found"
            500 -> "Internal Server Error"
            else -> "OK"
        }
        val header = "HTTP/1.1 $statusCode $statusText\r\n" +
                "Content-Type: $contentType\r\n" +
                "Content-Length: ${bodyBytes.size}\r\n" +
                "Access-Control-Allow-Origin: *\r\n" +
                "Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS\r\n" +
                "Access-Control-Allow-Headers: *\r\n" +
                "Connection: close\r\n\r\n"

        out.write(header.toByteArray(StandardCharsets.UTF_8))
        out.write(bodyBytes)
        out.flush()
    }

    override fun onServerStop() {
        activeSessions.values.forEach { session ->
            session.job.cancel()
            session.channel.close()
            try { session.socket.close() } catch (_: Exception) {}
        }
        activeSessions.clear()
        scope.cancel()
    }
}

package io.github.mucker.mcp

import android.content.Context
import io.github.mucker.Mucker
import io.github.mucker.core.MockEngine
import io.github.mucker.server.MuckerHttpServer

/**
 * Entry point to install Model Context Protocol (MCP) support into Mucker.
 */
object MuckerMcp {

    @JvmStatic
    fun install(server: MuckerHttpServer, engine: MockEngine, context: Context?): MuckerMcpPlugin {
        val plugin = MuckerMcpPlugin(engine, server.port, context)
        server.registerPlugin(plugin)
        return plugin
    }
}

/**
 * Kotlin extension function to enable MCP on a MuckerHttpServer instance.
 */
fun MuckerHttpServer.enableMcp(engine: MockEngine, context: Context?): MuckerMcpPlugin {
    return MuckerMcp.install(this, engine, context)
}

/**
 * Kotlin extension function to enable MCP on the Mucker singleton.
 */
fun Mucker.enableMcp(context: Context? = null): MuckerMcpPlugin? {
    val server = currentServer ?: return null
    return MuckerMcp.install(server, engine, context)
}
